"""Finite reduced-shank profile for the qualified FreeCAD 1.1.4 tool API.

This module is carried unchanged in reduced-tool editable bundles. Only installed
trusted code may admit a bundle before importing its copy or restoring a Job.
The embedded constrained profile is adaptor-generated data, never authored code."""
import base64,hashlib,math,uuid
import FreeCAD as A
from Path.Tool.shape.models.base import ToolBitShape
from Path.Tool.toolbit.models.base import ToolBit
from Path.Tool.toolbit.mixins import CuttingToolMixin,RotaryToolBitMixin
TEMPLATE=base64.b64decode(b'',validate=True)
if hashlib.sha256(TEMPLATE).hexdigest()!='0558049e8f8c387724137008bf1b6c7fdc17dac64ddbcb9d8502f066fa6f3ed4':raise RuntimeError('Installed reduced-tool template differs')
TYPES={'Diameter':'App::PropertyLength','Length':'App::PropertyLength','TipAngle':'App::PropertyAngle','CuttingEdgeHeight':'App::PropertyLength','ShankDiameter':'App::PropertyLength','Flutes':'App::PropertyInteger'}
DEFAULTS={'Diameter':'2 mm','Length':'16 mm','TipAngle':'90 deg','CuttingEdgeHeight':'3 mm','ShankDiameter':'1 mm','Flutes':2}

def validate(values):
 if set(values)!=set(TYPES) or type(values['Flutes']) is not int or not 1<=values['Flutes']<=12:raise ValueError('Finite reduced tool schema differs')
 numbers={k:float(v) for k,v in values.items() if k!='Flutes'}
 if any(not math.isfinite(v) for v in numbers.values()):raise ValueError('Nonfinite reduced tool dimension')
 d,l,a,c,s=(numbers[k] for k in ('Diameter','Length','TipAngle','CuttingEdgeHeight','ShankDiameter'))
 if not .1<=d<=100 or not 1<=a<=179 or not .1<=s<d or not .1<=c<=1000 or not d/2/math.tan(math.radians(a/2))<c<l<=2000:raise ValueError('Reduced tool profile relation differs')
 return values

class SCXReducedShape(ToolBitShape):
 name='SCXReducedDrill'
 aliases=('SCXReducedDrill',)
 @classmethod
 def schema(cls):return {k:({'Diameter':'Full cutting diameter','Length':'Physical bit length from tip','TipAngle':'Included physical cone angle','CuttingEdgeHeight':'Physical cutting end from tip','ShankDiameter':'Reduced noncutting shank diameter','Flutes':'Integral cutting flute count'}[k],t) for k,t in TYPES.items()}
 def __init__(self,id='SCXReducedDrill',**parameters):
  super().__init__(id)
  self._data=TEMPLATE;self._param_types=dict(TYPES);self._defaults=dict(DEFAULTS)
  self.set_parameters(**dict(DEFAULTS,**parameters))
 @property
 def label(self):return 'Reduced-shank pointed drill'
 def set_parameter(self,name,value):
  if name not in TYPES:raise ValueError('Foreign reduced profile parameter')
  return super().set_parameter(name,value)
 def make_body(self,doc):
  values=self.get_parameters()
  validate({k:(v if k=='Flutes' else v.Value) for k,v in values.items()})
  return super().make_body(doc)

class SCXReducedTool(ToolBit,CuttingToolMixin,RotaryToolBitMixin):
 SHAPE_CLASS=SCXReducedShape
 def __init__(self,shape,id=None):
  ToolBit.__init__(self,shape,id=id);CuttingToolMixin.__init__(self,self.obj)
 @property
 def summary(self):return 'Finite reduced-shank pointed tool'
 def __getstate__(self):return {'version':1}
 def __setstate__(self,state):
  if type(state) is not dict or set(state)!={'version'} or type(state['version']) is not int or state['version']!=1:raise ValueError('Foreign reduced tool proxy state')
  self._restore_version=1
 def onDocumentRestored(self,obj):
  if getattr(self,'_restore_version',None)!=1:raise ValueError('Missing finite restored proxy state')
  if obj.TypeId!='Part::FeaturePython' or obj.ShapeType!='SCXReducedDrill' or obj.ShapeID!='SCXReducedDrill':raise ValueError('Foreign reduced tool role or shape identity')
  if any(obj.getTypeIdOfProperty(k)!=t for k,t in TYPES.items()):raise ValueError('Reduced tool property types differ')
  values={k:(getattr(obj,k) if k=='Flutes' else getattr(obj,k).Value) for k in TYPES};validate(values)
  self.obj=obj;self.id=str(uuid.UUID(str(obj.ToolBitID)))
  if self.id!=obj.ToolBitID or obj.Material!='HSS' or obj.SpindleDirection!='Forward' or obj.ExpressionEngine:raise ValueError('Foreign reduced tool identity, material or expression state')
  self._in_update=True;self._suppress_visual_update=True;self._visual_update_queued=False
  try:
   self._tool_bit_shape=SCXReducedShape(**{k:(v if k=='Flutes' else str(v)+(' deg' if k=='TipAngle' else ' mm')) for k,v in values.items()})
   self._create_base_properties();self._update_tool_properties()
  finally:self._in_update=False;self._suppress_visual_update=False
